#!/bin/bash
set -e
GREEN="\033[0;32m"; YELLOW="\033[1;33m"; RED="\033[0;31m"; NC="\033[0m"
log()  { echo -e "${GREEN}[DEPLOY]${NC} $1"; }
warn() { echo -e "${YELLOW}[WARN]${NC} $1"; }
fail() { echo -e "${RED}[ERROR]${NC} $1"; exit 1; }

DIR="/home/automystics-scada/htdocs/scada.automystics.tech"
cd "$DIR" || fail "Deploy directory not found"
log "Working in $(pwd)"

log "[1/7] Writing updated source files..."
python3 - << 'PYEOF'
import base64, pathlib
files = {
  '.npmrc': '',
  'artifacts/api-server/src/lib/drivers/types.ts': '',
  'artifacts/api-server/src/lib/drivers/MqttDriver.ts': '',
  'artifacts/api-server/src/lib/seed.ts': '',
  'artifacts/api-server/src/routes/plants.ts': '',
  'artifacts/api-server/src/routes/alerts.ts': '',
  'artifacts/solar-scada/src/pages/plant-dashboard.tsx': '',
  'artifacts/solar-scada/src/pages/device-detail.tsx': '',
  'artifacts/solar-scada/src/pages/inverter-detail.tsx': '',
  'artifacts/solar-scada/src/pages/inverter-list.tsx': '',
  'artifacts/solar-scada/src/pages/platform-admin-login.tsx': '',
  'artifacts/solar-scada/src/pages/login.tsx': '',
  'artifacts/api-server/src/routes/auth-otp.ts': '',
  'artifacts/api-server/src/routes/platform-admin-auth.ts': '',
  'artifacts/api-server/src/routes/index.ts': '',
  'artifacts/api-server/src/lib/mailer.ts': '',
}
for p, b in files.items():
    pathlib.Path(p).parent.mkdir(parents=True, exist_ok=True)
    pathlib.Path(p).write_bytes(base64.b64decode(b))
    print(f"  wrote {p}")
PYEOF

log "[2/7] PostgreSQL setup..."
sudo -u postgres psql << 'SQL' 2>/dev/null || true
DO $$ BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'scada') THEN
    CREATE USER scada WITH PASSWORD 'scada';
  END IF;
END $$;
SQL
sudo -u postgres psql -c "CREATE DATABASE solar_scada OWNER scada;" 2>/dev/null || true
sudo -u postgres psql -d solar_scada -c "GRANT ALL ON SCHEMA public TO scada;" 2>/dev/null || true

log "[3/7] Installing nodemailer..."
pnpm --filter @workspace/api-server add nodemailer --silent 2>/dev/null || true

log "[4/7] DB migrations..."
pnpm --filter @workspace/db run db:push

log "[5/7] Building API..."
pnpm --filter @workspace/api-server run build

log "[6/7] Building frontend..."
PORT=3000 BASE_PATH=/ pnpm --filter @workspace/solar-scada run build

log "[7/7] Restarting services..."
systemctl daemon-reload
systemctl restart solar-scada-api
sleep 5
systemctl restart solar-scada-proxy 2>/dev/null || true
sleep 2

log "Health checks..."
API_STATUS=$(curl -s -o /dev/null -w "%{http_code}" http://127.0.0.1:8080/api/healthz)
if [ "$API_STATUS" = "200" ]; then log "API OK (HTTP $API_STATUS)"; else fail "API not responding (HTTP $API_STATUS)"; fi

TREND=$(curl -s -o /dev/null -w "%{http_code}" "http://127.0.0.1:8080/api/plants/plant-ana/trend?period=day")
log "Trend endpoint: HTTP $TREND"

echo ""
echo -e "${GREEN}✅ Deploy complete! (16 files)${NC}"
echo -e "${GREEN}   App:   https://scada.automystics.tech${NC}"
echo -e "${GREEN}   Admin: https://scada.automystics.tech/platform-admin${NC}"
echo ""
